{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
</style>
{#- Copies: same rules as "Sales Invoice Multi Copy Master" — draft → DRAFT COPY; ?print_all=1 → four
    copies; ?copy_name=… → that copy; else Original. -#}
{%- set print_all_val = frappe.form_dict.get('print_all') | string -%}
{%- set copy_param = frappe.form_dict.get('copy_name') -%}
{%- if doc.docstatus == 0 -%}{%- set copy_list = ["DRAFT COPY"] -%}
{%- elif print_all_val == "1" -%}{%- set copy_list = ["Original", "Duplicate", "Triplicate", "Quadruplicate"] -%}
{%- elif copy_param -%}{%- set copy_list = [copy_param] -%}
{%- else -%}{%- set copy_list = ["Original"] -%}{%- endif -%}
{%- set ns = namespace(line_discount=0.0) -%}
{%- for item in doc.items -%}{%- set ns.line_discount = ns.line_discount + ((item.discount_amount or 0) | float | abs) * ((item.qty or 0) | float | abs) -%}{%- endfor -%}
{%- set overall_discount = (doc.discount_amount or 0) | float | abs -%}
{%- set total_abs = (doc.rounded_total or doc.grand_total or 0) | float | abs -%}
{%- set fmt = "{:,.2f}" -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money((v or 0) | float | abs, currency=doc.currency) }}{%- endmacro -%}
{%- set words = frappe.utils.money_in_words(total_abs, "INR") | replace("INR ", "") | replace(" only.", "") | replace(" Only.", "") -%}
{%- set remarks = (doc.remarks or "") | trim -%}
{%- if remarks in ("No Remarks", "No remarks") -%}{%- set remarks = "" -%}{%- endif -%}
{#- the letter head is the PDF page header, so it prints on every page (docs/print-formats.md › Page header) -#}
<div id="header-html" class="hidden-pdf">{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}</div>
<div id="footer-html" class="visible-pdf"><p class="text-center small page-number visible-pdf" style="font-size:7.5pt;">Page <span class="page"></span> of <span class="topage"></span></p></div>
<style>
  /* page margins: the page header / footer set them (docs/print-formats.md › Page header) */
  .print-format > .page-break:last-child { page-break-after: auto; }
  /* terms written in the editor carry its "height: 100%" and scroll bars: inside the page box they stretched to the
     page and showed scroll arrows — the text keeps its own height */
  .print-format .ql-editor { height: auto !important; overflow: visible !important; padding: 0 !important; }
  .print-format .ql-editor p { margin: 0 !important; }
  /* letter head: tighter gaps (the Letter Head record is shared); the PDF page header's own 5mm bottom padding
     is the gap under the heading; a format with its own header (no letter head) starts at the header's top */
  .print-format .letter-head > div, .print-format .rn-letterhead > div, .print-format .pr-letterhead > div { margin-bottom: 1px !important; }
  .print-format .letter-head > div > div[style*="border-bottom"], .print-format .rn-letterhead > div > div[style*="border-bottom"],
  .print-format .pr-letterhead > div > div[style*="border-bottom"] { margin-top: 2px !important; }
  html body { padding-bottom: 1mm !important; }
  /* Page box (docs/print-formats.md › Blank rows): the page is a vertical box of at least the printable height
     (275mm here, measured for this format's header / footer); the items part stretches into the space left and
     its blank rows — a clipped table of empty rows after the items — fill it. Content taller than the page flows
     on to the next page; the box never shrinks it. */
  .rn-copy { display: -webkit-box; -webkit-box-orient: vertical; min-height: 239mm; }
  .dacs-items-box { -webkit-box-flex: 1; display: -webkit-box; -webkit-box-orient: vertical; }
  .dacs-fill-wrap { -webkit-box-flex: 1; height: 0; overflow: hidden; display: block !important; }
  .rn-items.dacs-fill { margin-top: -1px; }
  .rn-copy { page-break-after: always; font-family: Arial, sans-serif; color: #000; display: -webkit-box; -webkit-box-orient: vertical; min-height: 239mm; }
  .rn-copy:last-child { page-break-after: auto; }
  .rn-letterhead { width: 100%; margin-bottom: 2px; }
  .rn-head { position: relative; width: 100%; text-align: center; padding-top: 1px; margin-bottom: 4px; }
  .rn-title { font-size: 12pt; font-weight: bold; letter-spacing: 1px; line-height: 1.1; }
  .rn-sub { font-size: 9pt; line-height: 1.3; }
  .rn-hsn { margin-top: 3px; font-size: 7.5pt; }
  .rn-hsn table { width: 100% !important; }
  .rn-chip { position: absolute; top: 0; right: 0; border: 2px solid #000; width: 135px; padding: 5px; font-weight: bold;
             font-size: 11px; text-transform: uppercase; background: #fff; text-align: center; }
  .rn-box { width: 100%; border-collapse: collapse; border: 1.2px solid #000; font-size: 8.5pt; line-height: 1.15; table-layout: fixed; }
  .rn-box td { vertical-align: top; }
  .rn-left { width: 50%; padding: 3px 4px; border-right: 1.2px solid #000; }
  .rn-party { font-weight: bold; font-size: 10pt; text-transform: uppercase; margin-bottom: 1px; }
  .rn-grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .rn-grid td { padding: 2px 4px; vertical-align: top; }
  .rn-grid .l { font-weight: bold; width: 38%; white-space: nowrap; }
  .rn-hl { background: #f2f2f2; }
  .rn-items { width: 100%; border-collapse: collapse; font-size: 9pt; margin-top: 4px; table-layout: fixed; }
  .rn-items th { border: 1px solid #000; background: #f2f2f2; padding: 3px; font-weight: bold; }
  .rn-items td { border-left: 1px solid #000; border-right: 1px solid #000; padding: 2px 3px; vertical-align: top; }
  .rn-items td { border-bottom: 1px solid #d1d8dd; }  /* row lines as on the invoice, blank rows too */
  .dacs-fill-wrap { border-bottom: 1px solid #000; }
  .rn-r { text-align: right; } .rn-c { text-align: center; }
  .rn-sum { width: 100%; border-collapse: collapse; font-size: 9pt; margin-top: 3px; }
  .rn-sum td { padding: 1px 2px; }
  .rn-total td { background: #f2f2f2; border: 1px solid #000; font-weight: bold; font-size: 10pt; }
  .rn-words { border: 1px solid #000; padding: 3px 6px; background: #fafafa; font-size: 8.5pt; margin-top: 4px; }
  .rn-foot { width: 100%; border: 1px solid #000; border-top: none; border-collapse: collapse; table-layout: fixed; }
  .rn-reason { border: 1px solid #000; border-top: none; padding: 4px 6px; font-size: 8pt; }
  .rn-note { font-size: 8pt; margin-top: 3px; }
</style>
{#- Credit Note — a Sales Invoice return (is_return). Layout follows "Sales invoice Print Format 4";
    amounts print positive; the original invoice and the reason (Remarks) are shown as GST requires. -#}
{%- set orig = frappe.db.get_value("Sales Invoice", doc.return_against, ["posting_date", "po_no", "irn"], as_dict=1) if doc.return_against else None -%}
{#- page box only when the note surely fits on one page (item lines — long names count extra); a longer bill
    prints as plain flow (docs/print-formats.md › Blank rows) -#}
{%- set fu = namespace(n=0) -%}
{%- for it in doc.items -%}{%- set fu.n = fu.n + 1 + ((it.item_name or '') | length) // 40 + (1 if it.item_name != it.item_code else 0) -%}{%- endfor -%}
{%- if fu.n > 11 %}<style>.rn-copy { display: block !important; min-height: 0 !important; height: auto !important; }
.dacs-items-box { display: block !important; } .dacs-fill-wrap { display: none !important; }</style>
{%- else %}<style>.rn-copy { min-height: 0 !important; height: 239mm !important; /* dacs page height */ }</style>{%- endif %}
{%- for copy_label in copy_list %}
<div class="rn-copy">
  {#- The company header (Letter Head), as "Sales invoice Print Format 4" gets it — on every copy. -#}

  <div class="rn-head">
    <div class="rn-title">CREDIT NOTE</div>
    <div class="rn-sub">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong>
      {%- if doc.return_against %}<br>Against Invoice: <strong>{{ doc.return_against }}</strong>{% if orig %} dt. <strong>{{ frappe.utils.formatdate(orig.posting_date, "dd-MMM-yyyy") }}</strong>{% endif %}{% endif %}</div>
    <div class="rn-chip">{{ copy_label }}</div>
  </div>

  <table class="rn-box"><tr>
    <td class="rn-left">
      <div class="rn-party">M/s. {{ doc.customer_name }}</div>
      <div style="font-size:8.5pt;line-height:1.05;">{{ doc.address_display or "" }}</div>
      {% if doc.billing_address_gstin %}<div style="margin-top:3px;"><strong>G.S.T. : </strong>{{ doc.billing_address_gstin }}</div>{% endif %}
      {% if doc.place_of_supply %}<div><strong>Place of Supply : </strong>{{ doc.place_of_supply }}</div>{% endif %}
    </td>
    <td style="width:50%;padding:0;">
      <table class="rn-grid">
        <tr class="rn-hl"><td class="l">Original Invoice</td><td>: <strong>{{ doc.return_against or "— (direct credit note)" }}</strong></td></tr>
        <tr><td class="l">Invoice Date</td><td>: {{ frappe.utils.formatdate(orig.posting_date) if orig else "" }}</td></tr>
        <tr><td class="l">Order No. / Date</td><td>: {{ doc.po_no or (orig.po_no if orig else "") or "" }}{% if doc.po_date %} / {{ frappe.utils.formatdate(doc.po_date) }}{% endif %}</td></tr>
        {% if orig and orig.irn %}<tr><td class="l">Original IRN</td><td style="word-break:break-all;">: {{ orig.irn }}</td></tr>{% endif %}
        {% if doc.irn %}<tr><td class="l">Credit Note IRN</td><td style="word-break:break-all;">: {{ doc.irn }}</td></tr>{% endif %}
        <tr><td class="l">Type</td><td>: Sales return / credit to customer</td></tr>
      </table>
    </td>
  </tr></table>

  {#- Price List Rate and Discount print only when a line has a discount (a price below its list price);
    otherwise only Rate (docs/print-formats.md) -#}
{%- set dd = namespace(on=false) -%}
{%- for it in doc.items -%}{%- if (it.discount_amount or 0) | float > 0.005 or ((it.price_list_rate or 0) | float | abs - (it.rate or 0) | float | abs) > 0.005 -%}{%- set dd.on = true -%}{%- endif -%}{%- endfor -%}
{%- set dacs_disc = dd.on -%}
<style>.dacs-nodisc .dacs-d { display: none; }</style>
<div class="dacs-items-box">
  <table class="rn-items{{ '' if dacs_disc else ' dacs-nodisc' }}">
    <colgroup><col style="width:5%;"><col style="width:33%;"><col style="width:10%;"><col style="width:9%;"><col class="dacs-d" style="width:11%;"><col class="dacs-d" style="width:9%;"><col style="width:10%;"><col style="width:13%;"></colgroup>
    <thead><tr>
      <th style="width:5%;">#</th><th style="width:33%;text-align:left;">Item returned</th><th style="width:10%;">HSN</th>
      <th style="width:9%;">Qty</th><th class="dacs-d" style="width:11%;">List Rate</th><th class="dacs-d" style="width:9%;">Disc.</th>
      <th style="width:10%;">Rate</th><th style="width:13%;">Amount</th>
    </tr></thead>
    <tbody>
    {% for item in doc.items %}
      <tr>
        <td class="rn-c">{{ loop.index }}</td>
        <td>{{ item.item_name }}{% if item.item_name != item.item_code %}<div style="font-size:6.5pt;color:#444;">{{ item.item_code }}</div>{% endif %}</td>
        <td class="rn-c">{{ item.gst_hsn_code or "" }}</td>
        <td class="rn-r">{{ "{:g}".format((item.qty or 0) | float | abs) }} {{ item.uom or "" }}</td>
        <td class="dacs-d rn-r">{{ money(item.price_list_rate) }}</td>
        <td class="dacs-d rn-r">{{ money(item.discount_amount) if item.discount_amount else "" }}</td>
        <td class="rn-r">{{ money(item.rate) }}</td>
        <td class="rn-r">{{ money(item.amount) }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  <div class="dacs-fill-wrap">
<table class="rn-items dacs-fill{{ '' if dacs_disc else ' dacs-nodisc' }}">
<colgroup><col style="width:5%;"><col style="width:33%;"><col style="width:10%;"><col style="width:9%;"><col class="dacs-d" style="width:11%;"><col class="dacs-d" style="width:9%;"><col style="width:10%;"><col style="width:13%;"></colgroup>
<tbody>
{%- for i in range(60) %}<tr>{%- for c in range((8) - (0 if dacs_disc else 2)) %}<td>&nbsp;</td>{%- endfor %}</tr>{%- endfor %}
</tbody>
</table>
</div>
  </div>

  <table class="rn-sum"><tr>
    <td style="width:62%;vertical-align:bottom;">
      <div style="font-weight:bold;">Total Qty returned: {{ "{:g}".format((doc.total_qty or 0) | float | abs) }}</div>
      {% if doc.gst_breakup_table %}<div class="rn-hsn">{{ doc.gst_breakup_table }}</div>{% endif %}
    </td>
    <td style="width:38%;padding-left:10px;">
      <table style="width:100%;border-collapse:collapse;">
        <tr><td>Gross Total</td><td class="rn-r">{{ fmt.format(((doc.net_total or 0) | float | abs) + ns.line_discount + overall_discount) }}</td></tr>
        {% if ns.line_discount > 0.01 %}<tr><td>Line-wise Discount (-)</td><td class="rn-r">- {{ fmt.format(ns.line_discount) }}</td></tr>{% endif %}
        {% if overall_discount > 0.01 %}<tr><td>Overall Discount (-)</td><td class="rn-r">- {{ fmt.format(overall_discount) }}</td></tr>{% endif %}
        <tr style="border-top:0.5px solid #ccc;font-weight:bold;"><td>Taxable Value</td><td class="rn-r">{{ fmt.format((doc.net_total or 0) | float | abs) }}</td></tr>
        {% for tax in doc.taxes %}{% if tax.tax_amount and ((tax.tax_amount | float | abs) > 0.01) %}
        <tr><td>{{ tax.account_head.split(' - ')[0] }}</td><td class="rn-r">{{ fmt.format(tax.tax_amount | float | abs) }}</td></tr>
        {% endif %}{% endfor %}
        {% if doc.rounding_adjustment and ((doc.rounding_adjustment | float | abs) > 0.001) %}<tr><td>Round Off</td><td class="rn-r">{{ fmt.format(doc.rounding_adjustment | float | abs) }}</td></tr>{% endif %}
        <tr class="rn-total"><td>CREDIT TOTAL ₹</td><td class="rn-r">{{ fmt.format(total_abs) }}</td></tr>
      </table>
    </td>
  </tr></table>

  <div class="rn-words"><strong>Amount in Words:</strong> <span style="font-style:italic;font-weight:bold;">Rupees {{ words }} Only</span>
    <div class="rn-note">
      {% if doc.return_against %}This credit note reduces the amount payable by you against Invoice <strong>{{ doc.return_against }}</strong> by ₹ {{ fmt.format(total_abs) }}.
      {% else %}This amount of ₹ {{ fmt.format(total_abs) }} is credited to your account with us.{% endif %}
    </div>
  </div>
  {#- No Terms & Conditions here: an invoice's terms ("goods once sold…") contradict a return. -#}
  <table class="rn-foot"><tr>
    <td style="width:70%;font-size:7.5pt;border-right:1px solid #000;padding:4px 6px;vertical-align:top;">
      <div style="font-weight:bold;text-decoration:underline;margin-bottom:2px;">Reason / Remarks</div>
      <div style="white-space:pre-wrap;">{{ remarks or "—" }}</div>
    </td>
    <td style="width:30%;text-align:center;padding:8px 4px 4px;vertical-align:top;">
      <div style="font-size:8.5pt; font-weight:bold; margin-bottom:42px;">For {{ doc.company }}</div>
              <div style="display:inline-block; border-top:1px solid #000; padding-top:2px; width:90%; font-weight:bold; font-size:8.5pt;">Authorised Signatory</div>
    </td>
  </tr></table>
</div>
{%- endfor %}
